// 1. Ambil payload & header request
const headers = $input.item.json.headers || {};
const body = ($input.item.json.body && typeof $input.item.json.body === 'object') ? $input.item.json.body : $input.item.json || {};

// 2. Validasi Header Sumber (X-Webhook-Source wajib laravel-actstation)
const sourceHeader = headers['x-webhook-source'] || headers['X-Webhook-Source'] || '';
if (sourceHeader !== 'laravel-actstation') {
  throw new Error('Validasi gagal: Header X-Webhook-Source tidak valid atau bukan laravel-actstation.');
}

// 3. Validasi Event (Ekspektasi ketat: notification.email)
const event = String(body.event || '').trim();
if (event !== 'notification.email') {
  throw new Error('Validasi gagal: Event \'' + event + '\' tidak didukung. Ekspektasi: notification.email');
}

// 4. Validasi Message ID pada root payload (wajib ada, tidak membuat fake messageId)
const messageId = String(body.message_id || '').trim();
if (!messageId) {
  throw new Error('Validasi gagal: message_id wajib disertakan pada root payload.');
}

// 5. Validasi data payload
const data = (body.data && typeof body.data === 'object') ? body.data : {};

// Validasi Tipe Email (Enum ketat)
const validTypes = ['information', 'readiness', 'assignment', 'verification'];
const type = String(data.type || '').trim().toLowerCase();
if (!validTypes.includes(type)) {
  throw new Error('Validasi gagal: Tipe data email \'' + type + '\' tidak valid. Pilihan: ' + validTypes.join(', '));
}

// 6. Validasi Penerima (recipient_email dan recipient_name)
const recipientEmail = String(data.recipient_email || data.email || '').trim();
if (!recipientEmail || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(recipientEmail)) {
  throw new Error('Validasi gagal: recipient_email kosong atau format alamat email tidak valid.');
}
const recipientName = String(data.recipient_name || data.name || '').trim();

// 7. Validasi Subjek / Title
const subject = String(data.subject || data.title || '').trim();
if (!subject) {
  throw new Error('Validasi gagal: subject atau title email tidak boleh kosong.');
}

// 8. Validasi HTML Rendered dari Laravel (Workflow tidak menduplikasi template Blade)
const renderedHtml = data.html || data.rendered_html || '';
if (!renderedHtml || typeof renderedHtml !== 'string' || renderedHtml.trim().length === 0) {
  throw new Error('Validasi gagal: html kosong. Workflow ini hanya menerima HTML yang telah dirender resmi oleh Laravel.');
}

// 9. Validasi & Sanitasi Lampiran (Maksimal 3 berkas, SSRF Protection via fixed application origin)
const rawAttachments = Array.isArray(data.attachments) ? data.attachments : [];
if (rawAttachments.length > 3) {
  throw new Error('Validasi gagal: Jumlah lampiran melebihi batas maksimal (maks 3 berkas).');
}

const validatedAttachments = [];
if (rawAttachments.length > 0) {
  // Fixed workflow origin; do not access server environment variables.
  const rawBaseUrl = 'https://actstation.net';

  let parsedBase;
  try {
    parsedBase = new URL(rawBaseUrl);
  } catch (e) {
    throw new Error('Validasi gagal: Format origin aplikasi tidak valid.');
  }

  if (parsedBase.protocol !== 'https:') {
    throw new Error('Validasi gagal: Origin aplikasi wajib menggunakan protokol HTTPS.');
  }
  if (parsedBase.username || parsedBase.password) {
    throw new Error('Validasi gagal: Origin aplikasi tidak boleh mengandung kredensial pengguna.');
  }

  const allowedOrigin = parsedBase.origin.toLowerCase();

  for (let i = 0; i < rawAttachments.length; i++) {
    const att = rawAttachments[i];
    const attUrl = typeof att === 'string' ? att.trim() : (att && att.url ? String(att.url).trim() : '');
    const attName = (typeof att === 'object' && att && (att.name || att.filename))
      ? String(att.name || att.filename).trim()
      : ('lampiran_' + (i + 1));
    const attMime = (typeof att === 'object' && att && att.mime)
      ? String(att.mime).trim()
      : 'application/octet-stream';

    if (!attUrl) {
      throw new Error('Validasi gagal: URL lampiran ke-' + (i + 1) + ' kosong.');
    }

    let parsedUrl;
    try {
      parsedUrl = new URL(attUrl);
    } catch (err) {
      throw new Error('Validasi gagal: Format URL lampiran ke-' + (i + 1) + ' tidak valid.');
    }

    // Wajib HTTPS
    if (parsedUrl.protocol !== 'https:') {
      throw new Error('SSRF Block: Protokol lampiran ke-' + (i + 1) + ' ditolak. Wajib HTTPS.');
    }

    // Tanpa kredensial URL
    if (parsedUrl.username || parsedUrl.password) {
      throw new Error('SSRF Block: Kredensial pengguna tidak diizinkan pada URL lampiran ke-' + (i + 1) + '.');
    }

    // Exact origin match: skema + host + port harus sama persis (subdomain dan beda port ditolak)
    if (parsedUrl.origin.toLowerCase() !== allowedOrigin) {
      throw new Error('SSRF Block: Origin lampiran ke-' + (i + 1) + ' tidak cocok dengan origin aplikasi terdaftar.');
    }

    // Signed route path validation: /communication/{message}/attachments/{index}
    const routeRegex = /^\/communication\/([^/]+)\/attachments\/(\d+)$/;
    const match = parsedUrl.pathname.match(routeRegex);
    if (!match) {
      throw new Error('SSRF Block: Path lampiran ke-' + (i + 1) + ' tidak valid. Wajib mengikuti rute /communication/.../attachments/...');
    }

    // Verifikasi kecocokan parameter rute dengan message_id dan indeks berkas
    if (match[1] !== messageId || parseInt(match[2], 10) !== i) {
      throw new Error('SSRF Block: Parameter rute lampiran ke-' + (i + 1) + ' tidak cocok dengan message_id atau indeks berkas.');
    }

    // Verifikasi keberadaan token tanda tangan pada query param
    if (!parsedUrl.searchParams.has('signature')) {
      throw new Error('SSRF Block: Parameter tanda tangan rute lampiran ke-' + (i + 1) + ' tidak ditemukan.');
    }

    validatedAttachments.push({
      index: i,
      url: attUrl,
      filename: attName,
      mime: attMime,
      binary_prop: ('attachment_' + i)
    });
  }
}

return {
  json: {
    to: recipientEmail,
    recipient_name: recipientName,
    subject: subject,
    html: renderedHtml,
    type: type,
    message_id: messageId,
    attachments: validatedAttachments,
    attachment_count: validatedAttachments.length,
    has_attachments: validatedAttachments.length > 0
  }
};

// Pecah array lampiran menjadi item individual untuk diunduh secara sekuensial/paralel
const firstItem = $input.first().json;
const list = firstItem.attachments || [];
return list.map(att => ({
  json: {
    url: att.url,
    filename: att.filename,
    binary_prop: att.binary_prop,
    index: att.index,
    mime: att.mime,
    total_expected: firstItem.attachment_count,
    message_id: firstItem.message_id,
    to: firstItem.to,
    recipient_name: firstItem.recipient_name,
    subject: firstItem.subject,
    html: firstItem.html
  }
}));

// 1. Ambil metadata lampiran dari node persiapan unduhan via $('Siapkan Unduhan Lampiran').all()
const preparedItems = $('Siapkan Unduhan Lampiran').all();
const downloadedItems = $input.all();

if (!preparedItems || preparedItems.length === 0) {
  throw new Error('Unduh lampiran gagal: tidak ada metadata lampiran yang dipersiapkan.');
}

const expectedTotal = preparedItems.length;
if (!downloadedItems || downloadedItems.length !== expectedTotal) {
  throw new Error('Unduh lampiran gagal: jumlah berkas terunduh (' + (downloadedItems ? downloadedItems.length : 0) + ') tidak cocok dengan ekspektasi (' + expectedTotal + '). Fail-closed aktif.');
}

const firstJson = preparedItems[0].json;
const combinedBinary = {};
const propNames = [];
const MAX_ATTACHMENT_SIZE = 5 * 1024 * 1024; // 5MB

function parseFileSizeToBytes(val) {
  if (typeof val === 'number') return val;
  if (typeof val === 'string') {
    const clean = val.trim();
    if (/^\d+$/.test(clean)) return parseInt(clean, 10);
    const m = clean.match(/^([\d.]+)\s*(b|kb|mb|gb)?$/i);
    if (m) {
      const num = parseFloat(m[1]);
      const unit = (m[2] || 'b').toLowerCase();
      if (unit === 'gb') return num * 1024 * 1024 * 1024;
      if (unit === 'mb') return num * 1024 * 1024;
      if (unit === 'kb') return num * 1024;
      return num;
    }
  }
  return 0;
}

for (let i = 0; i < preparedItems.length; i++) {
  const meta = preparedItems[i].json;
  const downItem = downloadedItems[i];
  const binaryKeys = Object.keys((downItem && downItem.binary) || {});
  if (binaryKeys.length === 0) {
    throw new Error('Unduh lampiran gagal: berkas ke-' + (i + 1) + ' tidak memiliki data binary.');
  }

  const bKey = binaryKeys[0];
  const binData = downItem.binary[bKey];

  // Ukur ukuran berkas secara robust (getBinaryDataBuffer jika async helper tersedia, atau fileSize/bytes)
  let sizeInBytes = 0;
  if (typeof this !== 'undefined' && this.helpers && typeof this.helpers.getBinaryDataBuffer === 'function') {
    try {
      const buf = await this.helpers.getBinaryDataBuffer(i, bKey);
      if (buf && buf.length !== undefined) {
        sizeInBytes = buf.length;
      }
    } catch (e) {
      // fallback jika helper tidak mengembalikan buffer
    }
  }

  if (sizeInBytes === 0 && binData.fileSize !== undefined) {
    sizeInBytes = parseFileSizeToBytes(binData.fileSize);
  }

  if (sizeInBytes === 0 && binData.data) {
    try {
      sizeInBytes = Buffer.byteLength(binData.data, 'base64');
    } catch (e) {}
  }

  if (sizeInBytes > MAX_ATTACHMENT_SIZE) {
    throw new Error('Unduh lampiran gagal: ukuran berkas \'' + (meta.filename || ('ke-' + (i + 1))) + '\' melebihi batas 5MB (' + sizeInBytes + ' bytes).');
  }

  const finalProp = 'attachment_' + i;
  combinedBinary[finalProp] = binData;
  if (meta.filename) {
    combinedBinary[finalProp].fileName = meta.filename;
  }
  if (meta.mime && (!binData.mimeType || binData.mimeType === 'application/octet-stream')) {
    combinedBinary[finalProp].mimeType = meta.mime;
  }
  propNames.push(finalProp);
}

return [{
  json: {
    to: firstJson.to,
    recipient_name: firstJson.recipient_name,
    subject: firstJson.subject,
    html: firstJson.html,
    message_id: firstJson.message_id,
    attachment_names_csv: propNames.join(',')
  },
  binary: combinedBinary
}];

